        for(int i=0;i<n;i++){
            String t=sc.next();
            if(t.length()>1 || Character.isDigit(t.charAt(0)) || (t.charAt(0)=='-' && t.length()>1)) st.push(Long.parseLong(t));
            else { long b=st.pop(), a=st.pop(); switch(t.charAt(0)){case '+':st.push(a+b);break;case '-':st.push(a-b);break;case '*':st.push(a*b);break;default:st.push(a/b);} }
        }
        System.out.println(st.pop());
    }
}

