import java.util.*;
public class Main {
    sealed interface Result permits Ok, Error {}
    record Ok(int value) implements Result {}
    record Error(String message) implements Result {}
    public static void main(String[] args) {
        Scanner sc=new Scanner(System.in);
        int x=sc.nextInt();
        Result r=x>=0 ? new Ok(x*2) : new Error("NEGATIVE");
        if(r instanceof Ok o) System.out.println(o.value());
        else System.out.println(((Error)r).message());
    }
}

