import java.util.*;
public class Main {
    static class Node {
        int key, value; Node prev, next;
        Node(int k,int v){key=k;value=v;}
    }
    static class LRU {
        final int cap; final Map<Integer,Node> map=new HashMap<>();
        final Node head=new Node(0,0), tail=new Node(0,0);
        LRU(int c){cap=c;head.next=tail;tail.prev=head;}
        void remove(Node n){n.prev.next=n.next;n.next.prev=n.prev;}
        void addFirst(Node n){n.next=head.next;n.prev=head;head.next.prev=n;head.next=n;}
        int get(int k){Node n=map.get(k);if(n==null)return -1;remove(n);addFirst(n);return n.value;}
        void put(int k,int v){
            Node n=map.get(k);
            if(n!=null){n.value=v;remove(n);addFirst(n);return;}
            n=new Node(k,v);map.put(k,n);addFirst(n);
            if(map.size()>cap){Node last=tail.prev;remove(last);map.remove(last.key);}
        }
    }
    public static void main(String[] args){
        Scanner sc=new Scanner(System.in);int cap=sc.nextInt(),q=sc.nextInt();LRU c=new LRU(cap);
        for(int i=0;i<q;i++){String op=sc.next();int k=sc.nextInt();if(op.equals("GET"))System.out.println(c.get(k));else c.put(k,sc.nextInt());}
    }
}

