import java.util.*;
public class Main {
    static class Node{int value;Node next,random;Node(int v){value=v;}}
    public static void main(String[] args){
        Scanner sc=new Scanner(System.in);int n=sc.nextInt();
        if(n==0)return;
        Node[] original=new Node[n]; int[] r=new int[n];
        for(int i=0;i<n;i++) original[i]=new Node(sc.nextInt());
        for(int i=0;i<n;i++) r[i]=sc.nextInt();
        for(int i=0;i<n-1;i++) original[i].next=original[i+1];
        for(int i=0;i<n;i++) if(r[i]>=0) original[i].random=original[r[i]];
        Map<Node,Node> copy=new HashMap<>();
        for(Node cur:original) copy.put(cur,new Node(cur.value));
        for(Node cur:original){
            Node c=copy.get(cur);
            if(cur.next!=null)c.next=copy.get(cur.next);
            if(cur.random!=null)c.random=copy.get(cur.random);
        }
        for(Node cur:original){
            Node c=copy.get(cur);
            int ri=-1; if(c.random!=null){int idx=0; while(idx<original.length && copy.get(original[idx])!=c.random)idx++; if(idx<original.length) ri=idx;}
            System.out.println(c.value+" "+ri);
        }
    }
}
